const crypto = require('crypto');
const input = $input.first();
const secret = $env.SLACK_SIGNING_SECRET;
const headers = input.json.headers ?? {};
const timestamp = String(headers['x-slack-request-timestamp'] ?? '');
const signature = String(headers['x-slack-signature'] ?? '');
const rawBodyBase64 = input.binary?.data?.data;
if (!rawBodyBase64) throw new Error('Rejected Slack callback: raw request body unavailable');
const raw = Buffer.from(rawBodyBase64, 'base64').toString('utf8');
if (!secret || !timestamp || !signature || Math.abs(Date.now() / 1000 - Number(timestamp)) > 300) throw new Error('Rejected Slack callback: missing/expired signature data');
const expected = 'v0=' + crypto.createHmac('sha256', secret).update(`v0:${timestamp}:${raw}`).digest('hex');
if (expected.length !== signature.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))) throw new Error('Rejected Slack callback: invalid signature');
const payloadMatch = raw.match(/(?:^|&)payload=([^&]*)/);
const payloadText = payloadMatch ? decodeURIComponent(payloadMatch[1].replace(/\+/g, ' ')) : '';
const payload = JSON.parse(payloadText);
const button = payload.actions?.[0];
const value = JSON.parse(button?.value ?? '');
const actionMap = { approve_cluster: 'approve', reject_cluster: 'reject', split_cluster: 'split' };
const action = actionMap[button?.action_id];
if (!action || !value.cluster_id || !value.report_draft_id || !payload.user?.id || !button.action_ts) throw new Error('Rejected Slack callback: invalid action payload');
return [{ json: { cluster_id: value.cluster_id, report_draft_id: value.report_draft_id, action, actor_id: payload.user.id, callback_id: `${payload.user.id}:${button.action_id}:${button.action_ts}` } }];

const r = $json;
const document_title = `Support root-cause report — ${r.cluster_id}`;
const document_content = `Support ticket root-cause report

Summary
${r.summary}

Suspected root cause
${r.suspected_root_cause}

Impact
${r.impact}

Evidence
${JSON.stringify(r.evidence, null, 2)}

Recommended next step
${r.recommended_next_step}

Approved via Slack human review.`;
return [{ json: { ...r, document_title, document_content } }];

const report = $('Format approved report').item.json;
const doc = $json;
const google_doc_id = String(doc.documentId ?? doc.id ?? '');
if (!google_doc_id) throw new Error('Google Docs verification returned no document ID');
const expected = String(report.document_content ?? '').trim();
const actual = String(doc.content ?? '').trim();
if (!actual || !actual.includes(expected.slice(0, 80))) {
  throw new Error('Google Docs write verification failed: the generated document is empty or does not contain the report text. The report was not marked delivered.');
}
const google_doc_url = `https://docs.google.com/document/d/${google_doc_id}/edit`;
return [{ json: { ...report, google_doc_id, google_doc_url, reviewed_at: new Date().toISOString() } }];

if ($json.ok !== true) {
  throw new Error(`Engineering Slack alert was rejected: ${$json.error ?? 'unknown Slack error'}`);
}
return $input.all();
